// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createOwner, updateOwner, getOwner, deleteOwner } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:9966");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Request Body
    const ownersPostRequestBody: string = `{
        "address": "1 Contract Way",
        "city": "Madison",
        "firstName": "Phoneone",
        "lastName": "Updatecase",
        "phoneNumber": "6085550111"
    }`;

    const ownersPostResponse = await createOwner(client, ownersPostRequestBody, 201);
    expect(ownersPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(ownersPostResponse, "firstName"), 'firstName').toBe("Phoneone");
    expect(getResponseValue(ownersPostResponse, "lastName"), 'lastName').toBe("Updatecase");
    expect(getResponseValue(ownersPostResponse, "address"), 'address').toBe("1 Contract Way");
    expect(getResponseValue(ownersPostResponse, "city"), 'city').toBe("Madison");
    expect(getResponseValue(ownersPostResponse, "phoneNumber"), 'phoneNumber').toBe("6085550111");
    expect(getResponseValue(ownersPostResponse, "telephone"), 'telephone mirrors phoneNumber').toBe("6085550111");
    expect(Number(getResponseValue(ownersPostResponse, "id")), 'id').toBeGreaterThan(0);
    const ownerId = getResponseValue(ownersPostResponse, "id");

    // Request Body
    const owners999999PutRequestBody: string = `{
        "address": "1 Contract Way",
        "city": "Madison",
        "firstName": "Phoneone",
        "lastName": "Updatecase",
        "phoneNumber": "6085550222"
    }`;

    const owners999999PutResponse = await updateOwner(client, "999999", owners999999PutRequestBody, 404);
    expect(owners999999PutResponse.statusCode, 'status code').toBe(404);

    // Request Body
    const ownersOwnersPutRequestBody: string = `{
        "address": "2 Contract Way",
        "city": "Madison",
        "firstName": "Phoneone",
        "lastName": "Updatecase",
        "phoneNumber": "6085550222",
        "telephone": "6085550111"
    }`;

    const ownersOwnersPutResponse = await updateOwner(client, ownerId, ownersOwnersPutRequestBody, 204, {"telephone": getResponseValue(ownersPostResponse, "telephone")});
    expect(ownersOwnersPutResponse.statusCode, 'status code').toBe(204);

    const ownersOwnersGetResponse = await getOwner(client, ownerId, 200);
    expect(ownersOwnersGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(ownersOwnersGetResponse, "id"), 'id').toBe(ownerId);
    expect(getResponseValue(ownersOwnersGetResponse, "firstName"), 'firstName').toBe("Phoneone");
    expect(getResponseValue(ownersOwnersGetResponse, "lastName"), 'lastName').toBe("Updatecase");
    expect(getResponseValue(ownersOwnersGetResponse, "city"), 'city').toBe("Madison");
    expect(getResponseValue(ownersOwnersGetResponse, "address"), 'address updated by the PUT').toBe("2 Contract Way");
    expect(getResponseValue(ownersOwnersGetResponse, "phoneNumber"), 'phoneNumber updated by the PUT').toBe("6085550222");
    expect(getResponseValue(ownersOwnersGetResponse, "telephone"), 'telephone mirrors phoneNumber').toBe("6085550222");

    const ownersOwnersDeleteResponse = await deleteOwner(client, ownerId, 204);
    expect(ownersOwnersDeleteResponse.statusCode, 'status code').toBe(204);
});
